 private int dp(int n){return Math.round(n*getResources().getDisplayMetrics().density);}
 @Override public void onCreate(Bundle state){super.onCreate(state);if(state!=null){shown=LocalDate.parse(state.getString("shown",LocalDate.now().toString()));page=state.getInt("page",0);}render();}
 @Override public void onResume(){super.onResume();MealReceiver.schedule(this);if(root!=null && page==2){int y=scroll.getScrollY();settings();scroll.post(()->scroll.scrollTo(0,y));}}
 @Override protected void onSaveInstanceState(Bundle out){super.onSaveInstanceState(out);out.putString("shown",shown.toString());out.putInt("page",page);}
 @Override public void onRequestPermissionsResult(int request,String[] permissions,int[] results){super.onRequestPermissionsResult(request,permissions,results);if(request==4 && page==2)settings();}
 @Override public void onBackPressed(){if(page!=0){home();}else super.onBackPressed();}
 private void render(){if(page==1)guide();else if(page==2)settings();else home();}
 private LinearLayout column(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);return l;}
 private LinearLayout row(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.HORIZONTAL);l.setGravity(Gravity.CENTER_VERTICAL);return l;}
 private GradientDrawable rounded(int color,int radius){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(radius));return d;}
 private void gap(LinearLayout parent,int h){View v=new View(this);parent.addView(v,new LinearLayout.LayoutParams(1,dp(h)));}
 private TextView text(LinearLayout parent,String value,int size,int color,boolean bold){TextView t=new TextView(this);t.setText(value);t.setTextSize(size);t.setTextColor(color);t.setTextDirection(View.TEXT_DIRECTION_RTL);t.setGravity(Gravity.START);t.setFontFeatureSettings("kern");t.setLineSpacing(dp(3),1.05f);t.setTypeface(Typeface.create("sans-serif",bold?Typeface.BOLD:Typeface.NORMAL));parent.addView(t,new LinearLayout.LayoutParams(-1,-2));return t;}
 private ImageView icon(int resource,int size,int color){ImageView i=new ImageView(this);i.setImageResource(resource);if(color!=0)i.setImageTintList(ColorStateList.valueOf(color));i.setImportantForAccessibility(View.IMPORTANT_FOR_ACCESSIBILITY_NO);i.setLayoutParams(new LinearLayout.LayoutParams(dp(size),dp(size)));return i;}
 private LinearLayout card(LinearLayout parent,int color){LinearLayout c=column();c.setPadding(dp(20),dp(20),dp(20),dp(20));c.setBackground(rounded(color,24));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.bottomMargin=dp(16);parent.addView(c,lp);return c;}
 private Button action(LinearLayout parent,String label,int resource,boolean primary,Runnable run){Button b=new Button(this);b.setText(label);b.setAllCaps(false);b.setTextSize(18);b.setTypeface(Typeface.create("sans-serif-medium",Typeface.NORMAL));b.setTextColor(primary?Color.WHITE:TEAL);b.setMinHeight(dp(56));b.setMinimumHeight(dp(56));b.setPadding(dp(16),dp(10),dp(16),dp(10));b.setGravity(Gravity.CENTER);b.setBackground(new RippleDrawable(ColorStateList.valueOf(0x22176b60),rounded(primary?TEAL:0xffedf4ef,16),null));if(resource!=0){Drawable d=getDrawable(resource).mutate();d.setTint(primary?Color.WHITE:TEAL);d.setBounds(0,0,dp(22),dp(22));b.setCompoundDrawablesRelative(d,null,null,null);b.setCompoundDrawablePadding(dp(10));}LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.topMargin=dp(10);parent.addView(b,lp);b.setOnClickListener(v->run.run());return b;}
 private void base(int selected){page=selected;LinearLayout shell=column();shell.setLayoutDirection(View.LAYOUT_DIRECTION_RTL);shell.setBackgroundColor(CREAM);
 getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR|View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR);
 shell.setOnApplyWindowInsetsListener((v,insets)->{v.setPadding(insets.getSystemWindowInsetLeft(),insets.getSystemWindowInsetTop(),insets.getSystemWindowInsetRight(),insets.getSystemWindowInsetBottom());return insets.consumeSystemWindowInsets();});
 scroll=new ScrollView(this);scroll.setFillViewport(true);scroll.setClipToPadding(false);root=column();root.setPadding(dp(20),dp(22),dp(20),dp(12));scroll.addView(root);shell.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));
 LinearLayout nav=row();nav.setBackgroundColor(Color.WHITE);nav.setPadding(dp(8),dp(8),dp(8),dp(8));String[] labels={"وجباتي","الدليل","الإعدادات"};int[] icons={R.drawable.ic_bowl,R.drawable.ic_book,R.drawable.ic_settings};
 for(int n=0;n<3;n++){final int dest=n;LinearLayout item=column();item.setGravity(Gravity.CENTER);item.setPadding(dp(4),dp(8),dp(4),dp(8));item.setMinimumHeight(dp(64));item.setBackground(new RippleDrawable(ColorStateList.valueOf(0x22176b60),rounded(n==selected?0xffe2f2eb:Color.WHITE,18),null));item.addView(icon(icons[n],24,n==selected?TEAL:MUTED));TextView label=text(item,labels[n],16,n==selected?TEAL:MUTED,n==selected);label.setGravity(Gravity.CENTER);item.setContentDescription(labels[n]);item.setImportantForAccessibility(View.IMPORTANT_FOR_ACCESSIBILITY_YES);item.setFocusable(true);item.setOnClickListener(v->{page=dest;render();});LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,-2,1);lp.setMargins(dp(3),0,dp(3),0);nav.addView(item,lp);}
 shell.addView(nav);setContentView(shell);shell.requestApplyInsets();}
 private void heading(String title,String sub,int image){LinearLayout line=row();LinearLayout words=column();text(words,title,32,INK,true);text(words,sub,17,MUTED,false);line.addView(words,new LinearLayout.LayoutParams(0,-2,1));ImageView mark=icon(image,60,0);line.addView(mark);root.addView(line);gap(root,22);}
 private String time(int slot){int m=p().getInt("time"+slot,TIMES[slot]);return String.format(Locale.ROOT,"%02d:%02d",m/60,m%60);}
 private void home(){base(0);heading("لقمتي","كل لقمة، خطوة جميلة",R.drawable.ic_brand);LocalDate birth=MealReceiver.birth(this);
 if(birth==null){LinearLayout welcome=card(root,0xffe2f2eb);text(welcome,"أهلا بكما",30,TEAL,true);gap(welcome,12);text(welcome,"نكهات مغربية وخطوات صغيرة، من عمر 6 أشهر حتى عيد الميلاد الأول.",21,INK,false);gap(welcome,10);text(welcome,"لنبدأ بتاريخ ميلاد طفلتك، لتظهر الوجبات المناسبة لعمرها.",19,MUTED,false);action(welcome,"اختيار تاريخ الميلاد",R.drawable.ic_calendar,true,()->pickBirth());return;}
 LinearLayout hero=card(root,TEAL);text(hero,shown.equals(LocalDate.now())?"قائمة اليوم":"قائمة الوجبات",17,0xffd8eee7,false);gap(hero,6);text(hero,shown.format(DateTimeFormatter.ofPattern("EEEE، d MMMM",arabic)),25,Color.WHITE,true);gap(hero,8);text(hero,"عمر طفلتك: "+Plan.months(birth,shown)+" أشهر",18,Color.WHITE,false);gap(hero,16);
 progressText=text(hero,"",18,Color.WHITE,false);progress=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);progress.setProgressTintList(ColorStateList.valueOf(0xffefc98a));progress.setProgressBackgroundTintList(ColorStateList.valueOf(0xff3e8578));hero.addView(progress,new LinearLayout.LayoutParams(-1,dp(7)));updateProgress();
 LinearLayout dates=row();Button previous=action(dates,"السابق",0,false,()->{shown=shown.minusDays(1);home();});Button today=action(dates,"اليوم",R.drawable.ic_calendar,false,()->{shown=LocalDate.now();home();});Button next=action(dates,"التالي",0,false,()->{shown=shown.plusDays(1);home();});for(Button b:new Button[]{previous,today,next}){LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,-2,1);lp.setMargins(dp(3),0,dp(3),0);b.setLayoutParams(lp);b.setTextSize(16);}root.addView(dates);gap(root,22);
 if(Plan.supported(birth,shown)){text(root,"وجبات صغيرة، حب كبير",24,INK,true);gap(root,14);for(int s=0;s<3;s++)mealCard(birth,s);}else{LinearLayout c=card(root,0xffffedd7);text(c,"خطة عمر 6–11 شهرا",23,INK,true);gap(c,8);text(c,"انتهت الخطة أو لم يبدأ عمرها المناسب بعد. لا توجد وجبات أو تذكيرات خارج هذا العمر.",19,MUTED,false);}
 LinearLayout note=card(root,0xffeeebfa);text(note,"الرضعات أولا",21,0xff665395,true);gap(note,8);text(note,"حليب الأم أو الحليب الصناعي يبقى أساس التغذية خلال السنة الأولى. هذه أفكار وجبات وليست وصفة طبية.",18,INK,false);}
 private void updateProgress(){LocalDate birth=MealReceiver.birth(this);int count=p().getInt("count",1),done=0;boolean supported=birth!=null&&Plan.supported(birth,shown);if(supported)for(int s=0;s<3;s++)if(Plan.active(count,s)&&p().getBoolean("done:"+shown+":"+s,false))done++;progressText.setText(supported?"تم تقديم "+done+" من "+count+" وجبات":"خارج مدة البرنامج");progress.setMax(count);progress.setProgress(done);}
 private void mealCard(LocalDate birth,int slot){boolean active=Plan.active(p().getInt("count",1),slot);LinearLayout c=card(root,Color.WHITE);LinearLayout top=row();ImageView image=icon(new int[]{R.drawable.ic_sun,R.drawable.ic_bowl,R.drawable.ic_moon}[slot],52,ACCENTS[slot]);image.setPadding(dp(12),dp(12),dp(12),dp(12));image.setBackground(rounded(TINTS[slot],16));top.addView(image);LinearLayout names=column();names.setPadding(dp(12),0,dp(12),0);text(names,Plan.LABELS[slot],22,INK,true);text(names,time(slot),18,ACCENTS[slot],true);top.addView(names,new LinearLayout.LayoutParams(0,-2,1));c.addView(top);gap(c,16);
 if(!active){text(c,"غير مفعلة حاليا",20,MUTED,true);gap(c,6);text(c,"استمري في الرضعات حسب حاجتها. يمكنك تعديل عدد الوجبات في الإعدادات.",18,MUTED,false);return;}
 text(c,Plan.meal(birth,shown,slot),25,INK,true);action(c,"طريقة التحضير",R.drawable.ic_spoon,false,()->preparation(birth,slot));gap(c,8);CheckBox check=new CheckBox(this);check.setText("تم تقديم الوجبة");check.setTextSize(19);check.setTextColor(TEAL);check.setMinHeight(dp(52));check.setButtonTintList(ColorStateList.valueOf(TEAL));String key="done:"+shown+":"+slot;check.setChecked(p().getBoolean(key,false));check.setOnCheckedChangeListener((v,on)->{p().edit().putBoolean(key,on).apply();updateProgress();});c.addView(check);}
 private void preparation(LocalDate birth,int slot){LinearLayout content=column();content.setPadding(dp(24),dp(12),dp(24),dp(16));content.setLayoutDirection(View.LAYOUT_DIRECTION_RTL);text(content,Plan.meal(birth,shown,slot),25,INK,true);gap(content,14);text(content,Plan.preparation(slot,Plan.months(birth,shown)),21,INK,false);ScrollView sc=new ScrollView(this);sc.addView(content);new AlertDialog.Builder(this).setView(sc).setPositiveButton("حسنا",null).show();}
 private void pickBirth(){LocalDate d=MealReceiver.birth(this);if(d==null)d=LocalDate.now().minusMonths(6);DatePickerDialog dialog=new DatePickerDialog(this,(v,y,m,day)->{p().edit().putString("birth",LocalDate.of(y,m+1,day).toString()).apply();shown=LocalDate.now();MealReceiver.schedule(this);home();},d.getYear(),d.getMonthValue()-1,d.getDayOfMonth());dialog.getDatePicker().setMaxDate(System.currentTimeMillis());dialog.show();}
 private void settings(){base(2);heading("على إيقاع طفلتك","أوقات تناسب يومكما",R.drawable.ic_brand);
 LinearLayout profile=card(root,Color.WHITE);text(profile,"ملف طفلتك",23,INK,true);LocalDate b=MealReceiver.birth(this);text(profile,b==null?"أضيفي تاريخ ميلاد طفلتك":b.format(DateTimeFormatter.ofPattern("d MMMM yyyy",arabic)),19,MUTED,false);action(profile,"تعديل تاريخ الميلاد",R.drawable.ic_calendar,false,()->pickBirth());
 LinearLayout meals=card(root,Color.WHITE);text(meals,"عدد الوجبات",23,INK,true);gap(meals,10);text(meals,"ابدئي بكميات قليلة مرة يوميا عند بدء الطعام، ثم زيدي تدريجيا حسب استعدادها. عادة 2–3 وجبات بعمر 6–8 أشهر، ونحو 3 وجبات بعمر 9–11 شهرا. لا تتغير الوجبات المفعلة دون اختيارك.",18,MUTED,false);String[] options={"وجبة واحدة: الغداء","وجبتان: الفطور والغداء","ثلاث وجبات"};for(int i=0;i<3;i++){final int n=i+1;boolean chosen=p().getInt("count",1)==n;Button choice=action(meals,options[i],chosen?R.drawable.ic_check:R.drawable.ic_bowl,chosen,()->{p().edit().putInt("count",n).apply();MealReceiver.schedule(this);settings();});choice.setContentDescription(options[i]+(chosen?"، محددة":""));}
 LinearLayout times=card(root,Color.WHITE);text(times,"مواعيد الوجبات",23,INK,true);for(int s=0;s<3;s++){final int slot=s;int tm=p().getInt("time"+s,TIMES[s]);action(times,Plan.LABELS[s]+"   "+time(s),R.drawable.ic_clock,false,()->new TimePickerDialog(this,(v,h,m)->{p().edit().putInt("time"+slot,h*60+m).apply();MealReceiver.schedule(this);settings();},tm/60,tm%60,true).show());}
 LinearLayout reminders=card(root,0xffe2f2eb);text(reminders,"تذكير لطيف في وقته",23,INK,true);gap(reminders,12);Switch sw=new Switch(this);sw.setText("التذكيرات اليومية");sw.setTextSize(20);sw.setTextColor(INK);sw.setMinHeight(dp(56));sw.setSwitchPadding(dp(16));sw.setChecked(p().getBoolean("enabled",false));reminders.addView(sw);sw.setOnCheckedChangeListener((v,on)->{p().edit().putBoolean("enabled",on).apply();if(on&&Build.VERSION.SDK_INT>=33&&checkSelfPermission("android.permission.POST_NOTIFICATIONS")!=android.content.pm.PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{"android.permission.POST_NOTIFICATIONS"},4);MealReceiver.schedule(this);});gap(reminders,10);text(reminders,"التذكيرات تقريبية وقد تتأخر بسبب توفير البطارية. عند إيقاف التطبيق إجباريا، افتحيه مجددا لاستئنافها.",18,INK,false);gap(reminders,10);NotificationManager nm=(NotificationManager)getSystemService(NOTIFICATION_SERVICE);text(reminders,nm.areNotificationsEnabled()?"إذن الإشعارات متاح":"الإشعارات محظورة في إعدادات الهاتف",18,TEAL,true);
 action(reminders,"إعدادات إشعارات الهاتف",R.drawable.ic_bell,false,()->startActivity(new Intent("android.settings.APP_NOTIFICATION_SETTINGS").putExtra("android.provider.extra.APP_PACKAGE",getPackageName())));action(reminders,"تجربة إشعار الآن",R.drawable.ic_bell,true,()->{if(MealReceiver.birth(this)==null){Toast.makeText(this,"أضيفي تاريخ الميلاد أولا",Toast.LENGTH_LONG).show();return;}if(!nm.areNotificationsEnabled()){Toast.makeText(this,"فعلي إذن الإشعارات من إعدادات الهاتف",Toast.LENGTH_LONG).show();return;}MealReceiver.notifyMeal(this,1,true);});text(root,"لقمتي • الإصدار 1.1",16,MUTED,false);}
 private void guide(){base(1);heading("بداية مطمئنة","دليلك لكل خطوة صغيرة",R.drawable.ic_brand);String copy="• ابدئي قرب 6 أشهر عندما تستطيع الجلوس مع ثبات الرأس وتنسيق اليد والعين والفم وبلع الطعام.\n\n• الطعام مكمل للرضعات. قدمي رشفات ماء مع الوجبة؛ لا تجعلي حليب البقر مشروبا رئيسيا قبل السنة.\n\n• اجعليها جالسة بشكل مستقيم وراقبيها طوال الأكل. لا مكسرات كاملة، لا عنب كامل، لا قطع جزر نيئة ولا قطع صلبة.\n\n• لا عسل قبل 12 شهرا، ولا ملح أو سكر مضاف أو مكعبات مرق. الشاي والعصير غير ضروريين.\n\n• هذه دورة أفكار من 7 أيام تتكرر؛ ليست 180 وصفة مختلفة ولا نظاما غذائيا متكاملا. استعملي مكونات سبق تحملها في الوصفات المركبة.\n\n• أدخلي مسببات الحساسية واحدا في كل مرة وبكمية صغيرة نهارا: مثل البيض المطبوخ تماما، القمح، اللبن الطبيعي المبستر كامل الدسم، السمك منزوع الشوك أو معجون المكسرات المخفف داخل الطعام. إذا تم تحملها استمري في تقديمها بانتظام. لا تؤخريها لمجرد غيابها عن الدورة الأساسية. الشوفان قد يحتوي على آثار قمح.\n\n• عند أكزيما شديدة أو حساسية معروفة استشيري الطبيب قبل إدخال مسببات الحساسية. إذا ظهر تفاعل أوقفي الطعام واطلبي المشورة. صعوبة التنفس أو تورم اللسان أو انهيار الطفل حالة طارئة.\n\n• اغسلي اليدين والأدوات، اطبخي اللحم والدجاج تماما، وقدمي الطعام بعد أن يبرد لحرارة مناسبة. تخلصي مما بقي في طبق الطفلة.\n\n• الكمية والقوام حسب قدرتها وشهيتها. اعرضي هذه الأفكار على طبيبها إذا كان لديها صعوبة بلع أو مشكلة نمو.";String[] parts=copy.split("\\n\\n");int i=0;for(String part:parts){LinearLayout c=card(root,i%2==0?Color.WHITE:0xffedf4ef);text(c,String.format(arabic,"%02d",++i),18,TEAL,true);gap(c,8);text(c,part.replaceFirst("^•\\s*",""),20,INK,false);}action(root,"منظمة الصحة العالمية",R.drawable.ic_book,false,()->open("https://www.who.int/health-topics/complementary-feeding"));action(root,"إرشادات NHS",R.drawable.ic_book,false,()->open("https://www.nhs.uk/baby/weaning-and-feeding/babys-first-solid-foods/"));}
 private void open(String url){startActivity(new Intent(Intent.ACTION_VIEW,android.net.Uri.parse(url)));}
